/* Configurable percentage authority, owner delegation and Telegram notification demo. */
const telegramEvents=[['discount','Discount approval requests'],['booking','New booking / changes'],['payment','Payment evidence received'],['refund','Refund approval requests'],['inventory','Inventory variance / approval'],['license','License expiry reminders']];
function approvalSettings(){let s=opsState();if(!s.telegram){s.telegram={connected:true,bot:'@VenueDeskDemoBot',ownerChat:'@venue_owner_demo',events:Object.fromEntries(telegramEvents.map(([k])=>[k,true])),bindings:{},messages:[],delegations:[],audit:[]};if(!s.users.some(u=>u.id==='deputy')){if(!s.roles.some(r=>r.name==='Approval deputy'))s.roles.push({name:'Approval deputy',permissions:['approvals'],percent:0,amount:0});s.users.push({id:'deputy',name:'Omar Khan',email:'deputy@example.test',role:'Approval deputy',halls:['*'],active:true})}save()}s.telegram.events.discount=true;return s.telegram}
const nowStamp=()=>new Date().toISOString();
const dayStamp=(plus=0)=>{let d=new Date();d.setDate(d.getDate()+plus);return d.toISOString().slice(0,10)};
function auditApproval(action,detail){approvalSettings().audit.push({at:nowStamp(),by:actor().name,action,detail});save()}
function activeDelegation(g,at=Date.now()){return !g.revoked&&Date.parse(g.expires+'T23:59:59Z')>=at&&Date.parse(g.start+'T00:00:00Z')<=at&&opsState().users.some(u=>u.id===g.user&&u.active&&u.role!=='Owner')}
function delegationFor(user,r){if(!r||r.requester===user.id||!user.active)return null;return approvalSettings().delegations.find(g=>g.user===user.id&&activeDelegation(g)&&(g.hall==='*'||g.hall===r.hallId)&&(user.halls.includes('*')||user.halls.includes(r.hallId))&&r.subtotal>0&&r.discount/r.subtotal*100<=g.percent)}
function mayDecide(r){return !!r&&r.status==='Pending'&&r.requester!==actor().id&&(isOwner()||!!delegationFor(actor(),r))}
function sendMockTelegram(recipient,kind,message,requestId=''){let s=approvalSettings();if(kind!=='discount'&&!s.events[kind])return;let chat=recipient==='owner'?s.ownerChat:s.bindings[recipient];s.messages.unshift({id:'TG-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),to:recipient,chat:chat||'Not linked',at:nowStamp(),kind,message,requestId,status:!s.connected?'Telegram disconnected - in-panel alert':chat?'Simulated delivered':'Not linked - in-panel alert only'});save()}
function newDiscountRequest(h,t){if(!can('discount')||!hallAllowed(h)||isOwner()||!quote.reason.trim()||!Number.isFinite(t.discount)||t.discount<=discountCap(t)||t.discount>t.subtotal)return null;let fp=quoteFingerprint(h,t),existing=opsState().approvals.find(a=>a.fingerprint===fp&&a.requester===actor().id&&a.status==='Pending');if(existing)return existing;let r={id:'DISC-'+Date.now().toString().slice(-7),requester:actor().id,requesterName:actor().name,hall:h.name,hallId:h.id,customer:booking.name,subtotal:t.subtotal,discount:t.discount,total:t.total,reason:quote.reason,fingerprint:fp,status:'Pending',created:nowStamp()};opsState().approvals.push(r);let pct=(r.discount/r.subtotal*100).toFixed(2);let msg=`Discount approval requested\n${r.id} · ${r.hall}\nRequested by ${r.requesterName}\nQuote: ${money(r.subtotal)}\nDiscount: ${money(r.discount)} (${pct}%)\nFinal price: ${money(r.total)}\nReason: ${r.reason}\nOpen the secure VenueDesk Approval Center to decide.`;sendMockTelegram('owner','discount',msg,r.id);for(let u of opsState().users.filter(u=>u.role!=='Owner'&&delegationFor(u,r)))sendMockTelegram(u.id,'discount',msg,r.id);auditApproval('Discount requested',r.id);save();return r}
submitDiscountRequest=function(){let r=newDiscountRequest(chosenHall(),quoteTotals(chosenHall(),false));if(!r){toast('Enter a valid above-limit discount and a reason.');return}render();toast('Request queued for owner approval. Telegram delivery is simulated.')};
decideDiscount=function(i,decision){let r=opsState().approvals[i];if(!mayDecide(r)||!['Approved','Rejected'].includes(decision))return false;let g=isOwner()?null:delegationFor(actor(),r);r.status=decision;r.decidedBy=actor().id;r.decidedByName=actor().name;r.decisionAuthority=g?'Delegated approver':'Owner';r.delegationId=g?.id||null;r.decidedAt=nowStamp();auditApproval('Discount '+decision.toLowerCase(),r.id+' · '+r.decisionAuthority);sendMockTelegram('owner','discount',`${r.id} was ${decision.toLowerCase()} by ${actor().name} (${r.decisionAuthority}).`,r.id);if(r.requester!=='owner')sendMockTelegram(r.requester,'discount',`${r.id} was ${decision.toLowerCase()}. Return to the booking quote.`,r.id);save();return true};
const oldApprovedQuote=quoteEditor;
quoteEditor=function(h,p,publicMode){let html=oldApprovedQuote(h,p,publicMode),r=actorRole(),t=quoteTotals(h,publicMode);if(!publicMode&&!isOwner()){html=html.replace(`Your limit: ${r.percent}% and ${money(r.amount)} maximum (${money(discountCap(t))} on this quote).`,`Your discount authority: ${r.percent}% (up to ${money(discountCap(t))} on this quote).`).replace('Owner approved this exact quote.','Approved by the owner or authorized approver.').replace('Approval request pending. Switch to Owner to review.','Approval pending. The owner has been alerted; an authorized deputy may also decide.')}return html};
const oldRoleStaffPage=staffPage;
staffPage=function(){let r=opsState().roles[roleIndex]||opsState().roles[0],html=oldRoleStaffPage();if(staffTab==='roles'){html=html.replace(payInput('Maximum amount (PKR)','role-amount',r.amount,'number',true,'min="0" step="1"'),'').replace('Both limits apply. Anything above the lower limit requires independent owner approval. The Owner role is protected.','This percentage is the sole automatic discount ceiling. Anything above it requires owner or delegated approval. The Owner role is protected.')}return html+`<div class="actions">${btn('Approval delegation','go:approvalSettings','outline','shield')}${btn('Telegram settings','go:telegramSettings','outline','message')}</div>`};
roleSave=function(fd){let name=String(fd['role-name']||'').trim(),percent=Number(fd['role-percent']),s=opsState();if(!name||name.toLowerCase()==='owner'||String(fd['role-percent']).trim()===''||!Number.isFinite(percent)||percent<0||percent>100||s.roles.some((r,i)=>i!==roleIndex&&r.name.toLowerCase()===name.toLowerCase()))return false;let old=s.roles[roleIndex].name;s.roles[roleIndex]={name,percent,amount:0,permissions:permissionItems.filter(([k])=>fd['perm-'+k]).map(([k])=>k)};s.users.filter(u=>u.role===old).forEach(u=>u.role=name);auditApproval('Role permissions changed',name+' · '+percent+'% automatic discount');return true};
discountQueue=function(){let list=opsState().approvals;return card('Booking discount approvals',`<div class="approval-info"><div class="task-icon">${ic('shield')}</div><div><b>Above-limit discounts require approval.</b><p>The owner receives an alert. An active delegated approver may decide within their assigned limits. No one may approve their own request.</p></div></div><div class="actions" style="margin:12px 0">${btn('Telegram notifications','go:approvalNotifications','outline','bell')}${isOwner()?btn('Manage approval delegation','go:approvalSettings','outline','settings'):''}</div><div class="table-wrap"><table><thead><tr><th>Request / customer</th><th>Requested by</th><th>Discount</th><th>Reason</th><th>Status / decision</th><th>Actions</th></tr></thead><tbody>${list.map((r,i)=>{if(!isOwner()&&r.requester!==actor().id&&!delegationFor(actor(),r))return '';return `<tr><td>${esc(r.id)}<br><small>${esc(r.customer)} · ${esc(r.hall)}</small></td><td>${esc(r.requesterName)}</td><td>${money(r.discount)}<br><small>${r.subtotal>0?(r.discount/r.subtotal*100).toFixed(2):0}% of ${money(r.subtotal)}</small></td><td>${esc(r.reason)}</td><td>${badge(r.status)}${r.decidedByName?`<br><small>${esc(r.decidedByName)} · ${esc(r.decisionAuthority)}</small>`:''}</td><td>${mayDecide(r)?cfgButton('Approve','ops-discount-decision:'+i+':Approved','primary sm')+' '+cfgButton('Reject','ops-discount-decision:'+i+':Rejected','danger sm'):'—'}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No discount requests in your view.</td></tr>'}</tbody></table></div><p class="muted config-help">A decision applies only to the exact quotation; any price, guest or service change requires a new decision.</p>`)};
venueDefs.approvalSettings=def('Approval settings','Delegate authority securely.','shield',[],[],[],'');venueDefs.telegramSettings=def('Telegram notifications','Connect and configure your alert preferences.','message',[],[],[],'');venueDefs.approvalNotifications=def('Notification inbox','Review simulated Telegram delivery and in-panel alerts.','bell',[],[],[],'');
let settingsGroup=ownerGroups.find(g=>g[0]==='Settings & support')[1];settingsGroup.unshift(['approvalSettings','Approval delegation','shield'],['telegramSettings','Telegram notifications','message']);ownerGroups.find(g=>g[0]==='Daily work')[1].push(['approvalNotifications','Notifications','bell']);permsByPage.approvalSettings='owner';permsByPage.telegramSettings='owner';
const priorPageAllowed=pageAllowed;
pageAllowed=function(p){if(p==='approvals'&&approvalSettings().delegations.some(g=>g.user===actor().id&&activeDelegation(g)))return true;return priorPageAllowed(p)};
function grantDelegation(fd){if(!isOwner())return false;let s=approvalSettings(),user=opsState().users.find(u=>u.id===fd['delegate-user']&&u.active&&u.role!=='Owner'),percent=Number(fd['delegate-percent']),start=fd['delegate-start'],expires=fd['delegate-expires'],hall=fd['delegate-hall'];if(!user||!Number.isFinite(percent)||percent<0||percent>100||!start||!expires||expires<start||expires<dayStamp()||!(hall==='*'||configuredHalls().some(h=>h.id===hall))||(!user.halls.includes('*')&&(hall==='*'||!user.halls.includes(hall))))return false;s.delegations.push({id:'DLG-'+Date.now(),user:user.id,percent,start,expires,hall,revoked:false});auditApproval('Approval delegation granted',user.name+' · '+percent+'% through '+expires);return true}
function delegationPage(){let s=approvalSettings(),users=opsState().users.filter(u=>u.active&&u.role!=='Owner');return pagehead('Approval delegation','Authorize a trusted user to approve discount requests while you are unavailable.',btn('Open Approval Center','go:approvals','outline','shield'))+`<div class="grid-even">${card('Grant approval authority',`<form id="delegate-form"><div class="fields"><label class="field">Authorized user<select name="delegate-user" required>${users.map(u=>`<option value="${esc(u.id)}" ${u.id==='deputy'?'selected':''}>${esc(u.name)} · ${esc(u.role)}</option>`).join('')}</select></label>${payInput('Maximum discount they may approve (%)','delegate-percent',30,'number',true,'min="0" max="100" step="0.01"')}<label class="field span2">Hall scope<select name="delegate-hall"><option value="*">All halls</option>${configuredHalls().map(h=>`<option value="${esc(h.id)}">${esc(h.name)}</option>`).join('')}</select></label>${payInput('Starts on','delegate-start',dayStamp(),'date')}${payInput('Expires on','delegate-expires',dayStamp(30),'date')}</div><div class="note">The owner still receives the request. The delegated approver cannot approve their own discount or exceed their ceiling.</div><button class="btn gold" type="submit">Grant authority</button></form>`)}${card('How approval works',`<div class="approval-flow"><div><b>1. Staff requests a discount</b><small>Only above the role’s configured percentage.</small></div><div><b>2. Owner is notified</b><small>Telegram and in-panel request. Eligible deputies are notified too.</small></div><div><b>3. Independent approval</b><small>Owner or assigned user approves/rejects the exact quote.</small></div><div><b>4. Staff resumes booking</b><small>The approved quotation can proceed to payment.</small></div></div>${btn('Set up Telegram','go:telegramSettings','primary','message')}`)}</div>`+card('Delegated approvers',`<div class="table-wrap"><table><thead><tr><th>User</th><th>Scope</th><th>Ceiling</th><th>Validity</th><th>Status</th><th>Actions</th></tr></thead><tbody>${s.delegations.map((g,i)=>`<tr><td>${esc(opsState().users.find(u=>u.id===g.user)?.name||g.user)}</td><td>${esc(g.hall==='*'?'All halls':configuredHalls().find(h=>h.id===g.hall)?.name||'Former hall')}</td><td>${g.percent}%</td><td>${g.start} → ${g.expires}</td><td>${badge(g.revoked?'Revoked':activeDelegation(g)?'Active':'Inactive')}</td><td>${g.revoked?'—':cfgButton('Revoke','approval-revoke:'+i,'danger sm')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No delegates assigned. Grant authority to an existing staff user above.</td></tr>'}</tbody></table></div>`)}
function telegramPage(){let s=approvalSettings();return pagehead('Telegram notifications','Connect the venue to Telegram and choose which operational alerts to receive.',btn('Open notification inbox','go:approvalNotifications','outline','bell'))+metrics([['Connection',s.connected?'Demo connected':'Not connected','message'],['Owner alerts',s.events.discount?'Enabled':'Disabled','bell'],['Linked staff',Object.values(s.bindings).filter(Boolean).length.toString(),'users'],['Delivery','Simulation only','shield']])+`<form id="telegram-settings-form">${card('1. Connect your Telegram bot',`<div class="approval-info"><div class="task-icon telegram-icon">➤</div><div><b>Telegram integration</b><p>Register a venue-specific bot, securely configure its credentials on the server and link the owner and delegate accounts.</p></div></div><div class="fields" style="margin-top:15px">${payInput('Bot username (sample)','tg-bot',s.bot)}${payInput('Owner Telegram identity (sample)','tg-owner',s.ownerChat)}</div><div class="actions" style="margin-top:12px">${cfgButton(s.connected?'Disconnect demo':'Connect demo bot','tg-connect',s.connected?'outline':'primary','check')}${cfgButton('Send test notification (demo)','tg-test','outline','bell')}</div><div class="note">This mock does not collect bot tokens or call Telegram. Real bot secrets must be encrypted and never returned to browsers. Pairing must prove the Telegram account belongs to the user.</div>`)}${card('2. Choose notification events',`<div class="ops-perms">${telegramEvents.map(([k,l])=>payCheckbox('tg-event-'+k,l,s.events[k])).join('')}</div><p class="muted config-help">Approval requests always remain in the panel. Discount requests alert the owner and eligible delegates when Telegram is connected.</p>`)}${card('3. Link authorized users',`<div class="config-stack">${opsState().users.filter(u=>u.role!=='Owner'&&u.active).map(u=>`<div class="config-card"><h3>${esc(u.name)} · ${esc(u.role)}</h3>${payInput('Telegram identity (sample)','tg-user-'+u.id,s.bindings[u.id]||'','text',false)}<p class="muted config-help">Only receive alerts relevant to assigned permissions or delegated authority.</p></div>`).join('')}</div>`)}<button type="submit" class="btn gold">Save notification settings</button></form><div class="actions" style="margin-top:22px">${btn('Approval delegation','go:approvalSettings','outline','shield')}${btn('Payment methods','go:paymentMethods','outline','wallet')}</div>`}
function notificationPage(){let s=approvalSettings(),list=s.messages.filter(m=>isOwner()||m.to===actor().id);return pagehead('Notification inbox','Review in-panel alerts and simulated Telegram messages.',isOwner()?btn('Telegram settings','go:telegramSettings','outline','settings'):btn('Approval Center','go:approvals','outline','shield'))+card('Telegram delivery history',`<div class="notification-list">${list.map(m=>`<article class="telegram-message"><header><div class="task-icon telegram-icon">➤</div><div><b>${esc(m.chat)}</b><small>${esc(new Date(m.at).toLocaleString())} · ${esc(m.kind)}</small></div>${badge(m.status)}</header><pre>${esc(m.message)}</pre>${m.requestId?btn('Open Approval Center','go:approvals','primary sm','shield'):''}</article>`).join('')||'<div class="empty">No simulated messages yet. Send a test notification or request an above-limit discount.</div>'}</div><div class="note">No live Telegram messages have been sent. This is a preview of the production notification workflow.</div>`)+(isOwner()?card('Approval audit trail',`<div class="table-wrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Event</th><th>Details</th></tr></thead><tbody>${s.audit.slice().reverse().map(a=>`<tr><td>${esc(new Date(a.at).toLocaleString())}</td><td>${esc(a.by)}</td><td>${esc(a.action)}</td><td>${esc(a.detail)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No approval events yet.</td></tr>'}</tbody></table></div>`):'')}
const beforeApprovalGeneric=generic;
generic=function(c,key){if(key==='venue-approvalSettings')return delegationPage();if(key==='venue-telegramSettings')return telegramPage();if(key==='venue-approvalNotifications')return notificationPage();return beforeApprovalGeneric(c,key)};
const beforeApprovalAction=action;
action=function(s){if(s.startsWith('approval-revoke:')){if(!isOwner())return;let g=approvalSettings().delegations[+s.split(':')[1]];if(g&&!g.revoked){g.revoked=true;auditApproval('Delegation revoked',g.id);render();toast('Delegated authority revoked.')}return}if(s==='tg-connect'){if(!isOwner())return;let t=approvalSettings();t.connected=!t.connected;save();render();return}if(s==='tg-test'){if(!isOwner())return;let t=approvalSettings();if(!t.connected){toast('Connect the demo bot first.');return}let prev=t.events.discount;t.events.discount=true;sendMockTelegram('owner','discount','VenueDesk test notification. Your demo connection is ready.');t.events.discount=prev;save();toast('Test notification appears in the mock inbox.');return}if(s==='notifications'&&mode==='venue'){route('venue','approvalNotifications');return}beforeApprovalAction(s)};
const beforeApprovalRecordAction=recordAction;
recordAction=function(key,i,a){if(key==='venue-approvals'&&!isOwner()&&a!=='View'){toast('Only the owner or an explicitly authorized approver can decide.');return}beforeApprovalRecordAction(key,i,a)};
document.addEventListener('submit',e=>{if(!['delegate-form','telegram-settings-form'].includes(e.target.id))return;e.preventDefault();e.stopImmediatePropagation();if(!isOwner())return;let fd=Object.fromEntries(new FormData(e.target));if(e.target.id==='delegate-form'){if(!grantDelegation(fd)){toast('Choose a valid staff user, hall scope, percentage and dates.');return}render();toast('Approval authority granted.');return}let s=approvalSettings();s.bot=fd['tg-bot'];s.ownerChat=fd['tg-owner'];s.events=Object.fromEntries(telegramEvents.map(([k])=>[k,!!fd['tg-event-'+k]]));for(let u of opsState().users.filter(u=>u.role!=='Owner'))s.bindings[u.id]=fd['tg-user-'+u.id]||'';auditApproval('Notification settings updated','Telegram preferences and sample user bindings');render();toast('Telegram demo settings saved.')},true);
const beforeTelegramPage=telegramPage;
telegramPage=function(){let s=approvalSettings(),html=beforeTelegramPage();return html.replace(payCheckbox('tg-event-discount','Discount approval requests',s.events.discount),payCheckbox('tg-event-discount','Discount approval requests (required)',true,true)).replace('Approval requests always remain in the panel.','Discount approval alerts are mandatory when Telegram is connected. Approval requests always remain in the panel.').replace('<div class="actions" style="margin-top:12px"><button','<div class="fields" style="margin-top:12px"><label class="field">Bot token (secure server setting)<input disabled value="••••••••••••••••"></label><label class="field">Account pairing<small>Production: one-time pairing code verified by the bot.</small><input disabled value="Demo pairing only"></label></div><div class="actions" style="margin-top:12px"><button')};
const beforeApprovalPay=completeMockPayment;
completeMockPayment=function(fd,h,publicMode){let ok=beforeApprovalPay(fd,h,publicMode);if(ok){let d=opsState().deals[booking.reference];if(d){sendMockTelegram('owner','booking',`New booking request ${d.reference}\nHall: ${d.hall}\nTotal: ${money(d.total)}\nStatus: ${d.status}`);if(d.claimed>0)sendMockTelegram('owner','payment',`Deposit evidence received for ${d.reference}\nAmount: ${money(d.claimed)}\nReview in VenueDesk before posting.`)}}return ok};
const decisionAction=action;
action=function(s){if(s.startsWith('ops-discount-decision:')){let [,idx,v]=s.split(':');if(decideDiscount(+idx,v)){render();toast('Approval decision saved.')}else toast('You are not authorized to decide this request.');return}decisionAction(s)};
approvalSettings();render();
